internal object LauncherTranslationChunk4 {
    val entries = mapOf(
        "Installation cancelled" to arrayOf("Kanselado ang pag-install", "\uC124\uCE58 \uCDE8\uC18C\uB428", "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u304C\u30AD\u30E3\u30F3\u30BB\u30EB\u3055\u308C\u307E\u3057\u305F", "\u5B89\u88C5\u5DF2\u53D6\u6D88", "Instalaci\u00F3n cancelada", "Vi\u1EC7c c\u00E0i \u0111\u1EB7t \u0111\u00E3 b\u1ECB h\u1EE7y", "Pemasangan dibatalkan", "Instala\u00E7\u00E3o cancelada"),
        "Installation permission is needed" to arrayOf("Kailangan ang pahintulot sa pag-install", "\uC124\uCE58 \uAD8C\uD55C\uC774 \uD544\uC694\uD569\uB2C8\uB2E4", "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u306E\u8A31\u53EF\u304C\u5FC5\u8981\u3067\u3059", "\u9700\u8981\u5B89\u88C5\u6743\u9650", "Se necesita permiso de instalaci\u00F3n", "C\u1EA7n quy\u1EC1n c\u00E0i \u0111\u1EB7t", "Izin pemasangan diperlukan", "Permiss\u00E3o de instala\u00E7\u00E3o necess\u00E1ria"),
        "Installation was cancelled. The verified download is still saved." to arrayOf("Kinansela ang pag-install. Ang na-verify na download ay nananatiling nakatago.", "\uC124\uCE58\uAC00 \uCDE8\uC18C\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uD655\uC778\uB41C \uB2E4\uC6B4\uB85C\uB4DC\uB294 \uC5EC\uC804\uD788 \uC800\uC7A5\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4.", "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u306F\u30AD\u30E3\u30F3\u30BB\u30EB\u3055\u308C\u307E\u3057\u305F\u3002\u691C\u8A3C\u6E08\u307F\u306E\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u306F\u307E\u3060\u4FDD\u5B58\u3055\u308C\u3066\u3044\u307E\u3059\u3002", "\u5B89\u88C5\u5DF2\u53D6\u6D88\u3002\u5DF2\u9A8C\u8BC1\u7684\u4E0B\u8F7D\u4ECD\u7136\u4FDD\u7559\u3002", "La instalaci\u00F3n fue cancelada. La descarga verificada todav\u00EDa est\u00E1 guardada.", "Vi\u1EC7c c\u00E0i \u0111\u1EB7t \u0111\u00E3 b\u1ECB h\u1EE7y. T\u1EC7p t\u1EA3i xu\u1ED1ng \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c minh v\u1EABn c\u00F2n l\u01B0u.", "Pemasangan dibatalkan. Unduhan yang sudah diverifikasi masih tersimpan.", "Instala\u00E7\u00E3o foi cancelada. O download verificado ainda est\u00E1 salvo."),
        "Installed add-on is current" to arrayOf("Ang naka-install na add-on ay kasalukuyan", "\uC124\uCE58\uB41C \uC560\uB4DC\uC628\uC774 \uCD5C\uC2E0\uC785\uB2C8\uB2E4", "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u6E08\u307F\u306E\u30A2\u30C9\u30AA\u30F3\u306F\u6700\u65B0\u3067\u3059", "\u5DF2\u5B89\u88C5\u7684\u63D2\u4EF6\u662F\u6700\u65B0\u7684", "El complemento instalado est\u00E1 actualizado", "Ph\u1EA7n b\u1ED5 tr\u1EE3 \u0111\u00E3 c\u00E0i \u0111\u1EB7t \u0111ang \u1EDF phi\u00EAn b\u1EA3n hi\u1EC7n t\u1EA1i", "Add-on yang terpasang sudah terbaru", "Complemento instalado est\u00E1 atualizado"),
        "Installed add-on publication could not be identified" to arrayOf("Hindi matukoy ang publikasyon ng naka-install na add-on", "\uC124\uCE58\uB41C \uC560\uB4DC\uC628 \uCD9C\uD310\uC744 \uD655\uC778\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u6E08\u307F\u30A2\u30C9\u30AA\u30F3\u306E\u516C\u958B\u60C5\u5831\u3092\u78BA\u8A8D\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u8BC6\u522B\u5DF2\u5B89\u88C5\u63D2\u4EF6\u7684\u7248\u672C", "No se pudo identificar la publicaci\u00F3n del complemento instalado", "Kh\u00F4ng th\u1EC3 x\u00E1c \u0111\u1ECBnh \u0111\u01B0\u1EE3c xu\u1EA5t b\u1EA3n c\u1EE7a ph\u1EA7n b\u1ED5 tr\u1EE3 \u0111\u00E3 c\u00E0i \u0111\u1EB7t", "Publikasi add-on yang terpasang tidak dapat diidentifikasi", "Publica\u00E7\u00E3o do complemento instalado n\u00E3o p\u00F4de ser identificada"),
        "Installed add-on updates" to arrayOf("Na-update ang naka-install na add-on", "\uC124\uCE58\uB41C \uC560\uB4DC\uC628 \uC5C5\uB370\uC774\uD2B8", "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u6E08\u307F\u30A2\u30C9\u30AA\u30F3\u3092\u66F4\u65B0\u3057\u307E\u3057\u305F", "\u5DF2\u5B89\u88C5\u63D2\u4EF6\u66F4\u65B0", "Actualizaciones del complemento instalado", "\u0110\u00E3 c\u1EADp nh\u1EADt ph\u1EA7n b\u1ED5 tr\u1EE3 \u0111\u00E3 c\u00E0i \u0111\u1EB7t", "Pembaruan add-on terpasang", "Atualiza\u00E7\u00F5es do complemento instalado"),
        "Installed build verified on this device" to arrayOf("Naverify ang naka-install na build sa device na ito", "\uC774 \uC7A5\uCE58\uC5D0\uC11C \uC124\uCE58\uB41C \uBE4C\uB4DC\uAC00 \uD655\uC778\uB418\uC5C8\uC2B5\uB2C8\uB2E4", "\u3053\u306E\u30C7\u30D0\u30A4\u30B9\u3067\u30D3\u30EB\u30C9\u304C\u78BA\u8A8D\u3055\u308C\u307E\u3057\u305F", "\u5DF2\u5728\u6B64\u8BBE\u5907\u4E0A\u9A8C\u8BC1\u7684\u5DF2\u5B89\u88C5\u7248\u672C", "Compilaci\u00F3n instalada verificada en este dispositivo", "Phi\u00EAn b\u1EA3n c\u00E0i \u0111\u1EB7t \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c minh tr\u00EAn thi\u1EBFt b\u1ECB n\u00E0y", "Build yang terpasang diverifikasi di perangkat ini", "Build instalado verificado neste dispositivo"),
        "Installed game could not be inspected" to arrayOf("Hindi masuri ang naka-install na laro", "\uC124\uCE58\uB41C \uAC8C\uC784\uC744 \uAC80\uC0AC\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u6E08\u307F\u30B2\u30FC\u30E0\u3092\u78BA\u8A8D\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u68C0\u67E5\u5DF2\u5B89\u88C5\u7684\u6E38\u620F", "No se pudo inspeccionar el juego instalado", "Kh\u00F4ng th\u1EC3 ki\u1EC3m tra tr\u00F2 ch\u01A1i \u0111\u00E3 c\u00E0i \u0111\u1EB7t", "Game yang terpasang tidak dapat diperiksa", "Jogo instalado n\u00E3o p\u00F4de ser inspecionado"),
        "Installed package verified on this device" to arrayOf("Naverify ang naka-install na package sa device na ito", "\uC774 \uC7A5\uCE58\uC5D0\uC11C \uC124\uCE58\uB41C \uD328\uD0A4\uC9C0\uAC00 \uD655\uC778\uB418\uC5C8\uC2B5\uB2C8\uB2E4", "\u3053\u306E\u30C7\u30D0\u30A4\u30B9\u3067\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u6E08\u307F\u30D1\u30C3\u30B1\u30FC\u30B8\u304C\u78BA\u8A8D\u3055\u308C\u307E\u3057\u305F", "\u5DF2\u5728\u6B64\u8BBE\u5907\u4E0A\u9A8C\u8BC1\u7684\u5DF2\u5B89\u88C5\u5305", "Paquete instalado verificado en este dispositivo", "G\u00F3i c\u00E0i \u0111\u1EB7t \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c minh tr\u00EAn thi\u1EBFt b\u1ECB n\u00E0y", "Paket yang terpasang diverifikasi di perangkat ini", "Pacote instalado verificado neste dispositivo"),
        "Installer wait cancelled by the user" to arrayOf("Kinansela ng user ang paghihintay sa installer", "\uC0AC\uC6A9\uC790\uAC00 \uC124\uCE58 \uD504\uB85C\uADF8\uB7A8 \uB300\uAE30\uB97C \uCDE8\uC18C\uD588\uC2B5\uB2C8\uB2E4", "\u30E6\u30FC\u30B6\u30FC\u306B\u3088\u3063\u3066\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u306E\u5F85\u6A5F\u304C\u30AD\u30E3\u30F3\u30BB\u30EB\u3055\u308C\u307E\u3057\u305F", "\u7528\u6237\u5DF2\u53D6\u6D88\u5B89\u88C5\u7A0B\u5E8F\u7B49\u5F85", "Espera del instalador cancelada por el usuario", "Vi\u1EC7c ch\u1EDD c\u00E0i \u0111\u1EB7t \u0111\u00E3 b\u1ECB ng\u01B0\u1EDDi d\u00F9ng h\u1EE7y", "Penantian installer dibatalkan oleh pengguna", "Espera do instalador cancelada pelo usu\u00E1rio"),
        "Installing {0} shell" to arrayOf("Ini-install ang {0} shell", "{0} \uC178\uC744 \uC124\uCE58 \uC911\uC785\uB2C8\uB2E4", "{0} \u30B7\u30A7\u30EB\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u4E2D", "\u6B63\u5728\u5B89\u88C5 {0} \u5916\u58F3", "Instalando la interfaz {0}", "\u0110ang c\u00E0i \u0111\u1EB7t {0} shell", "Memasang {0} shell", "Instalando o shell {0}"),
        "Its architecture cannot run on this device's Android system." to arrayOf("Ang arkitektura nito ay hindi maaaring tumakbo sa Android system ng device na ito.", "\uD574\uB2F9 \uC544\uD0A4\uD14D\uCC98\uB294 \uC774 \uC7A5\uCE58\uC758 Android \uC2DC\uC2A4\uD15C\uC5D0\uC11C \uC2E4\uD589\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.", "\u3053\u306E\u30A2\u30FC\u30AD\u30C6\u30AF\u30C1\u30E3\u306F\u3053\u306E\u30C7\u30D0\u30A4\u30B9\u306EAndroid\u30B7\u30B9\u30C6\u30E0\u3067\u5B9F\u884C\u3067\u304D\u307E\u305B\u3093\u3002", "\u5B83\u7684\u67B6\u6784\u65E0\u6CD5\u5728\u6B64\u8BBE\u5907\u7684 Android \u7CFB\u7EDF\u4E0A\u8FD0\u884C\u3002", "Su arquitectura no puede ejecutarse en el sistema Android de este dispositivo.", "Ki\u1EBFn tr\u00FAc c\u1EE7a n\u00F3 kh\u00F4ng th\u1EC3 ch\u1EA1y tr\u00EAn h\u1EC7 th\u1ED1ng Android c\u1EE7a thi\u1EBFt b\u1ECB n\u00E0y.", "Arsitekturnya tidak dapat dijalankan pada sistem Android perangkat ini.", "Sua arquitetura n\u00E3o pode rodar no sistema Android deste dispositivo."),
        "Jester Mods could not authorize this download. Refresh the add-on or update details, then try again." to arrayOf("Hindi ma-authorize ng Jester Mods ang download na ito. I-refresh ang add-on o i-update ang mga detalye, pagkatapos subukan muli.", "Jester Mods\uAC00 \uC774 \uB2E4\uC6B4\uB85C\uB4DC\uB97C \uC2B9\uC778\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uC560\uB4DC\uC628\uC744 \uC0C8\uB85C \uACE0\uCE58\uAC70\uB098 \uC138\uBD80 \uC815\uBCF4\uB97C \uC5C5\uB370\uC774\uD2B8\uD55C \uD6C4 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC2ED\uC2DC\uC624.", "Jester Mods \u306F\u3053\u306E\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3092\u8A8D\u8A3C\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u30A2\u30C9\u30AA\u30F3\u306E\u66F4\u65B0\u307E\u305F\u306F\u60C5\u5831\u3092\u66F4\u65B0\u3057\u3066\u304B\u3089\u3001\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "Jester Mods \u65E0\u6CD5\u6388\u6743\u6B64\u4E0B\u8F7D\u3002\u8BF7\u5237\u65B0\u63D2\u4EF6\u6216\u66F4\u65B0\u8BE6\u7EC6\u4FE1\u606F\uFF0C\u7136\u540E\u91CD\u8BD5\u3002", "Jester Mods no pudo autorizar esta descarga. Actualice el complemento o los detalles de la actualizaci\u00F3n, y luego intente de nuevo.", "Jester Mods kh\u00F4ng th\u1EC3 \u1EE7y quy\u1EC1n cho vi\u1EC7c t\u1EA3i xu\u1ED1ng n\u00E0y. L\u00E0m m\u1EDBi ph\u1EA7n b\u1ED5 tr\u1EE3 ho\u1EB7c c\u1EADp nh\u1EADt th\u00F4ng tin chi ti\u1EBFt, sau \u0111\u00F3 th\u1EED l\u1EA1i.", "Jester Mods tidak dapat mengotorisasi unduhan ini. Segarkan add-on atau perbarui detailnya, lalu coba lagi.", "Jester Mods n\u00E3o p\u00F4de autorizar este download. Atualize o complemento ou os detalhes, e tente novamente."),
        "Jester Mods could not establish a trusted connection, so nothing was accepted. Check the device date and network, then retry." to arrayOf("Hindi makapagtatag ng pinagkakatiwalaang koneksyon ang Jester Mods, kaya walang tinanggap. Suriin ang petsa ng aparato at network, pagkatapos ay subukang muli.", "Jester Mods\uAC00 \uC2E0\uB8B0\uD560 \uC218 \uC788\uB294 \uC5F0\uACB0\uC744 \uC124\uC815\uD560 \uC218 \uC5C6\uC5B4 \uC544\uBB34 \uAC83\uB3C4 \uC218\uB77D\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uAE30\uAE30 \uB0A0\uC9DC\uC640 \uB124\uD2B8\uC6CC\uD06C\uB97C \uD655\uC778\uD55C \uD6C4 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "Jester Mods\u306F\u4FE1\u983C\u3067\u304D\u308B\u63A5\u7D9A\u3092\u78BA\u7ACB\u3067\u304D\u306A\u304B\u3063\u305F\u305F\u3081\u3001\u4F55\u3082\u53D7\u3051\u5165\u308C\u3089\u308C\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u30C7\u30D0\u30A4\u30B9\u306E\u65E5\u4ED8\u3068\u30CD\u30C3\u30C8\u30EF\u30FC\u30AF\u3092\u78BA\u8A8D\u3057\u3066\u3001\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "Jester Mods \u65E0\u6CD5\u5EFA\u7ACB\u53D7\u4FE1\u4EFB\u7684\u8FDE\u63A5\uFF0C\u56E0\u6B64\u672A\u63A5\u53D7\u4EFB\u4F55\u5185\u5BB9\u3002\u8BF7\u68C0\u67E5\u8BBE\u5907\u65E5\u671F\u548C\u7F51\u7EDC\uFF0C\u7136\u540E\u91CD\u8BD5\u3002", "Jester Mods no pudo establecer una conexi\u00F3n confiable, por lo que no se acept\u00F3 nada. Verifica la fecha del dispositivo y la red, luego int\u00E9ntalo de nuevo.", "Jester Mods kh\u00F4ng th\u1EC3 thi\u1EBFt l\u1EADp k\u1EBFt n\u1ED1i tin c\u1EADy, v\u00EC v\u1EADy kh\u00F4ng c\u00F3 g\u00EC \u0111\u01B0\u1EE3c ch\u1EA5p nh\u1EADn. Ki\u1EC3m tra ng\u00E0y v\u00E0 m\u1EA1ng c\u1EE7a thi\u1EBFt b\u1ECB, sau \u0111\u00F3 th\u1EED l\u1EA1i.", "Jester Mods tidak dapat membangun koneksi yang tepercaya, sehingga tidak ada yang diterima. Periksa tanggal perangkat dan jaringan, lalu coba lagi.", "Jester Mods n\u00E3o p\u00F4de estabelecer uma conex\u00E3o confi\u00E1vel, ent\u00E3o nada foi aceito. Verifique a data do dispositivo e a rede, depois tente novamente."),
        "Jester Mods could not verify this private add-on approval. Connect and try again." to arrayOf("Hindi ma-verify ng Jester Mods ang pag-apruba ng pribadong add-on na ito. Kumonekta at subukang muli.", "Jester Mods\uAC00 \uC774 \uAC1C\uC778 \uC560\uB4DC\uC628 \uC2B9\uC778\uC744 \uD655\uC778\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uC5F0\uACB0\uD55C \uD6C4 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "Jester Mods\u306F\u3053\u306E\u30D7\u30E9\u30A4\u30D9\u30FC\u30C8\u30A2\u30C9\u30AA\u30F3\u306E\u627F\u8A8D\u3092\u78BA\u8A8D\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u63A5\u7D9A\u3057\u3066\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "Jester Mods \u65E0\u6CD5\u9A8C\u8BC1\u6B64\u79C1\u4EBA\u63D2\u4EF6\u7684\u6279\u51C6\u3002\u8BF7\u8FDE\u63A5\u540E\u91CD\u8BD5\u3002", "Jester Mods no pudo verificar esta aprobaci\u00F3n de complemento privado. Con\u00E9ctate y vuelve a intentarlo.", "Jester Mods kh\u00F4ng th\u1EC3 x\u00E1c minh s\u1EF1 ph\u00EA duy\u1EC7t add-on ri\u00EAng t\u01B0 n\u00E0y. K\u1EBFt n\u1ED1i v\u00E0 th\u1EED l\u1EA1i.", "Jester Mods tidak dapat memverifikasi persetujuan add-on pribadi ini. Sambungkan dan coba lagi.", "Jester Mods n\u00E3o conseguiu verificar a aprova\u00E7\u00E3o deste addon privado. Conecte-se e tente novamente."),
        "Jester Mods could not write the file inside its app storage. Restart the device and check that Android storage is available, then try again." to arrayOf("Hindi maisulat ng Jester Mods ang file sa loob ng storage ng app nito. I-restart ang aparato at tiyaking available ang storage ng Android, pagkatapos ay subukang muli.", "Jester Mods\uAC00 \uC571 \uC800\uC7A5\uC18C \uB0B4\uC5D0 \uD30C\uC77C\uC744 \uC4F8 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uAE30\uAE30\uB97C \uC7AC\uC2DC\uC791\uD558\uACE0 Android \uC800\uC7A5\uC18C\uAC00 \uC0AC\uC6A9 \uAC00\uB2A5\uD55C\uC9C0 \uD655\uC778\uD55C \uD6C4 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "Jester Mods\u306F\u30A2\u30D7\u30EA\u306E\u30B9\u30C8\u30EC\u30FC\u30B8\u5185\u306B\u30D5\u30A1\u30A4\u30EB\u3092\u66F8\u304D\u8FBC\u3080\u3053\u3068\u304C\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u30C7\u30D0\u30A4\u30B9\u3092\u518D\u8D77\u52D5\u3057\u3001Android\u306E\u30B9\u30C8\u30EC\u30FC\u30B8\u304C\u5229\u7528\u53EF\u80FD\u3067\u3042\u308B\u3053\u3068\u3092\u78BA\u8A8D\u3057\u3066\u304B\u3089\u3001\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "Jester Mods \u65E0\u6CD5\u5728\u5176\u5E94\u7528\u5B58\u50A8\u4E2D\u5199\u5165\u6587\u4EF6\u3002\u8BF7\u91CD\u542F\u8BBE\u5907\u5E76\u68C0\u67E5 Android \u5B58\u50A8\u662F\u5426\u53EF\u7528\uFF0C\u7136\u540E\u91CD\u8BD5\u3002", "Jester Mods no pudo escribir el archivo dentro de su almacenamiento de la aplicaci\u00F3n. Reinicia el dispositivo y verifica que el almacenamiento de Android est\u00E9 disponible, luego int\u00E9ntalo de nuevo.", "Jester Mods kh\u00F4ng th\u1EC3 ghi t\u1EC7p v\u00E0o b\u1ED9 nh\u1EDB \u1EE9ng d\u1EE5ng. Kh\u1EDFi \u0111\u1ED9ng l\u1EA1i thi\u1EBFt b\u1ECB v\u00E0 ki\u1EC3m tra b\u1ED9 nh\u1EDB Android c\u00F3 s\u1EB5n, sau \u0111\u00F3 th\u1EED l\u1EA1i.", "Jester Mods tidak dapat menulis file di dalam penyimpanan aplikasinya. Mulai ulang perangkat dan periksa bahwa penyimpanan Android tersedia, lalu coba lagi.", "Jester Mods n\u00E3o p\u00F4de gravar o arquivo dentro do armazenamento do aplicativo. Reinicie o dispositivo e verifique se o armazenamento do Android est\u00E1 dispon\u00EDvel, depois tente novamente."),
        "Jester Mods support code" to arrayOf("Suporta ng code ng Jester Mods", "Jester Mods \uC9C0\uC6D0 \uCF54\uB4DC", "Jester Mods\u30B5\u30DD\u30FC\u30C8\u30B3\u30FC\u30C9", "Jester Mods \u652F\u6301\u4EE3\u7801", "C\u00F3digo de soporte de Jester Mods", "M\u00E3 h\u1ED7 tr\u1EE3 Jester Mods", "Kode dukungan Jester Mods", "C\u00F3digo de suporte Jester Mods"),
        "Jester Mods will open Android's uninstall confirmation. The add-on stays safely in your Library." to arrayOf("Bubuksan ng Jester Mods ang kumpirmasyon ng pag-uninstall ng Android. Mananatiling ligtas ang add-on sa iyong Library.", "Jester Mods\uAC00 Android\uC758 \uC81C\uAC70 \uD655\uC778\uC744 \uC5FD\uB2C8\uB2E4. \uC560\uB4DC\uC628\uC740 \uC548\uC804\uD558\uAC8C \uB77C\uC774\uBE0C\uB7EC\uB9AC\uC5D0 \uB0A8\uC544 \uC788\uC2B5\uB2C8\uB2E4.", "Jester Mods\u306FAndroid\u306E\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u78BA\u8A8D\u3092\u958B\u304D\u307E\u3059\u3002\u30A2\u30C9\u30AA\u30F3\u306F\u5B89\u5168\u306B\u30E9\u30A4\u30D6\u30E9\u30EA\u306B\u6B8B\u308A\u307E\u3059\u3002", "Jester Mods \u5C06\u6253\u5F00 Android \u7684\u5378\u8F7D\u786E\u8BA4\u3002\u63D2\u4EF6\u5C06\u5B89\u5168\u4FDD\u7559\u5728\u60A8\u7684\u5E93\u4E2D\u3002", "Jester Mods abrir\u00E1 la confirmaci\u00F3n de desinstalaci\u00F3n de Android. El complemento permanece seguro en tu Biblioteca.", "Jester Mods s\u1EBD m\u1EDF x\u00E1c nh\u1EADn g\u1EE1 c\u00E0i \u0111\u1EB7t c\u1EE7a Android. Add-on v\u1EABn an to\u00E0n trong Th\u01B0 vi\u1EC7n c\u1EE7a b\u1EA1n.", "Jester Mods akan membuka konfirmasi pencopotan pemasangan Android. Add-on tetap aman di Perpustakaan Anda.", "Jester Mods abrir\u00E1 a confirma\u00E7\u00E3o de desinstala\u00E7\u00E3o do Android. O addon permanece seguro em sua Biblioteca."),
        "Jester Mods will verify the installed build when you return." to arrayOf("Veveripikahin ng Jester Mods ang naka-install na build kapag bumalik ka.", "Jester Mods\uB294 \uB3CC\uC544\uC62C \uB54C \uC124\uCE58\uB41C \uBE4C\uB4DC\uB97C \uD655\uC778\uD569\uB2C8\uB2E4.", "Jester Mods\u306F\u623B\u3063\u305F\u3068\u304D\u306B\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3055\u308C\u3066\u3044\u308B\u30D3\u30EB\u30C9\u3092\u78BA\u8A8D\u3057\u307E\u3059\u3002", "Jester Mods \u5728\u60A8\u8FD4\u56DE\u65F6\u5C06\u9A8C\u8BC1\u5DF2\u5B89\u88C5\u7684\u7248\u672C\u3002", "Jester Mods verificar\u00E1 la versi\u00F3n instalada cuando regreses.", "Jester Mods s\u1EBD x\u00E1c minh b\u1EA3n c\u00E0i \u0111\u1EB7t khi b\u1EA1n quay l\u1EA1i.", "Jester Mods akan memverifikasi build yang terpasang saat Anda kembali.", "Jester Mods verificar\u00E1 a vers\u00E3o instalada quando voc\u00EA retornar."),
