        "JesterMoodsPrivateModule" to arrayOf("JesterMoodsPrivateModule", "JesterMoods\uAC1C\uC778\uBAA8\uB4C8", "JesterMoods\u30D7\u30E9\u30A4\u30D9\u30FC\u30C8\u30E2\u30B8\u30E5\u30FC\u30EB", "JesterMoods\u79C1\u4EBA\u6A21\u5757", "JesterMoodsM\u00F3duloPrivado", "M\u00F4-\u0111un ri\u00EAng t\u01B0 JesterMoods", "JesterMoodsModulPribadi", "M\u00F3duloPrivadoDeHumoresDoBobo"),
        "JesterMoodsStorage" to arrayOf("JesterMoodsStorage", "JesterMoods\uC2A4\uD1A0\uB9AC\uC9C0", "JesterMoods\u30B9\u30C8\u30EC\u30FC\u30B8", "JesterMoods\u5B58\u50A8", "JesterMoodsAlmacenamiento", "L\u01B0u tr\u1EEF JesterMoods", "JesterMoodsPenyimpanan", "ArmazenamentoDeHumoresDoBobo"),
        "JesterMoodsUpdate" to arrayOf("JesterMoodsUpdate", "JesterMoods\uC5C5\uB370\uC774\uD2B8", "JesterMoods\u30A2\u30C3\u30D7\u30C7\u30FC\u30C8", "JesterMoods\u66F4\u65B0", "JesterMoodsActualizaci\u00F3n", "C\u1EADp nh\u1EADt JesterMoods", "JesterMoodsPerbarui", "Atualiza\u00E7\u00E3oDeHumoresDoBobo"),
        "Keep Jester Mods open while the verified game downloads." to arrayOf("Panatilihing bukas ang Jester Mods habang nagda-download ang na-verify na laro.", "\uAC80\uC99D\uB41C \uAC8C\uC784\uC774 \uB2E4\uC6B4\uB85C\uB4DC\uB418\uB294 \uB3D9\uC548 Jester Mods\uB97C \uC5F4\uC5B4 \uB450\uC138\uC694.", "\u691C\u8A3C\u6E08\u307F\u30B2\u30FC\u30E0\u306E\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u4E2D\u306BJester Mods\u3092\u958B\u3044\u305F\u307E\u307E\u306B\u3059\u308B\u3002", "\u5728\u9A8C\u8BC1\u6E38\u620F\u4E0B\u8F7D\u65F6\u4FDD\u6301 Jester Mods \u6253\u5F00\u3002", "Mant\u00E9n Jester Mods abierto mientras se descarga el juego verificado.", "Gi\u1EEF cho c\u00E1c b\u1EA3n mod Jester m\u1EDF trong khi tr\u00F2 ch\u01A1i \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c minh \u0111ang t\u1EA3i xu\u1ED1ng.", "Biarkan Jester Mods terbuka saat game yang diverifikasi sedang diunduh.", "Mantenha os mods do Jester abertos enquanto o jogo verificado \u00E9 baixado."),
        "Keeping the resumable download intact for a future retry." to arrayOf("Pinananatiling buo ang resumable download para sa susunod na pagtatangkang muli.", "\uD5A5\uD6C4 \uC7AC\uC2DC\uB3C4\uB97C \uC704\uD574 \uC7AC\uAC1C \uAC00\uB2A5\uD55C \uB2E4\uC6B4\uB85C\uB4DC\uB97C \uADF8\uB300\uB85C \uC720\uC9C0\uD569\uB2C8\uB2E4.", "\u5C06\u6765\u306E\u518D\u8A66\u884C\u306E\u305F\u3081\u306B\u518D\u958B\u53EF\u80FD\u306A\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3092\u4FDD\u6301\u3059\u308B\u3002", "\u4FDD\u6301\u53EF\u7EED\u4E0B\u8F7D\u4EE5\u4FBF\u5C06\u6765\u91CD\u8BD5\u3002", "Manteniendo la descarga reanudable intacta para un reintento futuro.", "Gi\u1EEF nguy\u00EAn b\u1EA3n t\u1EA3i xu\u1ED1ng c\u00F3 th\u1EC3 ti\u1EBFp t\u1EE5c cho l\u1EA7n th\u1EED l\u1EA1i trong t\u01B0\u01A1ng lai.", "Menjaga unduhan yang dapat dilanjutkan tetap utuh untuk percobaan ulang di masa depan.", "Mantendo o download resum\u00EDvel intacto para uma nova tentativa futura."),
        "Keeping the resumable package intact for a future retry." to arrayOf("Pinananatiling buo ang resumable package para sa susunod na pagtatangkang muli.", "\uD5A5\uD6C4 \uC7AC\uC2DC\uB3C4\uB97C \uC704\uD574 \uC7AC\uAC1C \uAC00\uB2A5\uD55C \uD328\uD0A4\uC9C0\uB97C \uADF8\uB300\uB85C \uC720\uC9C0\uD569\uB2C8\uB2E4.", "\u5C06\u6765\u306E\u518D\u8A66\u884C\u306E\u305F\u3081\u306B\u518D\u958B\u53EF\u80FD\u306A\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u4FDD\u6301\u3059\u308B\u3002", "\u4FDD\u6301\u53EF\u7EED\u5305\u4EE5\u4FBF\u5C06\u6765\u91CD\u8BD5\u3002", "Manteniendo el paquete reanudable intacto para un reintento futuro.", "Gi\u1EEF nguy\u00EAn g\u00F3i c\u00F3 th\u1EC3 ti\u1EBFp t\u1EE5c cho l\u1EA7n th\u1EED l\u1EA1i trong t\u01B0\u01A1ng lai.", "Menjaga paket yang dapat dilanjutkan tetap utuh untuk percobaan ulang di masa depan.", "Mantendo o pacote resum\u00EDvel intacto para uma nova tentativa futura."),
        "Latest release is ready" to arrayOf("Handa na ang pinakabagong release", "\uCD5C\uC2E0 \uBC84\uC804 \uB9B4\uB9AC\uC2A4\uAC00 \uC900\uBE44\uB418\uC5C8\uC2B5\uB2C8\uB2E4", "\u6700\u65B0\u30EA\u30EA\u30FC\u30B9\u306E\u6E96\u5099\u304C\u6574\u3044\u307E\u3057\u305F", "\u6700\u65B0\u7248\u672C\u5DF2\u51C6\u5907\u597D", "La \u00FAltima versi\u00F3n est\u00E1 lista", "Phi\u00EAn b\u1EA3n m\u1EDBi nh\u1EA5t \u0111\u00E3 s\u1EB5n s\u00E0ng", "Rilis terbaru siap", "A vers\u00E3o mais recente est\u00E1 pronta"),
        "Launch failed" to arrayOf("Nabigong magsimula", "\uC2E4\uD589 \uC2E4\uD328", "\u8D77\u52D5\u306B\u5931\u6557\u3057\u307E\u3057\u305F", "\u542F\u52A8\u5931\u8D25", "Fall\u00F3 el lanzamiento", "Kh\u1EDFi ch\u1EA1y th\u1EA5t b\u1EA1i", "Peluncuran gagal", "Falha ao iniciar"),
        "Launcher access is required" to arrayOf("Kinakailangan ang access sa launcher", "\uB7F0\uCC98 \uC561\uC138\uC2A4\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4", "\u30E9\u30F3\u30C1\u30E3\u30FC\u3078\u306E\u30A2\u30AF\u30BB\u30B9\u304C\u5FC5\u8981\u3067\u3059", "\u9700\u8981\u8BBF\u95EE\u542F\u52A8\u5668", "Se requiere acceso al launcher", "C\u1EA7n quy\u1EC1n truy c\u1EADp c\u1EE7a launcher", "Akses peluncur diperlukan", "\u00C9 necess\u00E1rio acesso ao lan\u00E7ador"),
        "Launcher module storage is unavailable" to arrayOf("Hindi magagamit ang storage ng launcher module", "\uB7F0\uCC98 \uBAA8\uB4C8 \uC2A4\uD1A0\uB9AC\uC9C0\uB97C \uC0AC\uC6A9\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30E9\u30F3\u30C1\u30E3\u30FC\u30E2\u30B8\u30E5\u30FC\u30EB\u306E\u30B9\u30C8\u30EC\u30FC\u30B8\u304C\u5229\u7528\u3067\u304D\u307E\u305B\u3093", "\u542F\u52A8\u5668\u6A21\u5757\u5B58\u50A8\u4E0D\u53EF\u7528", "El almacenamiento del m\u00F3dulo del launcher no est\u00E1 disponible", "B\u1ED9 nh\u1EDB m\u00F4-\u0111un launcher kh\u00F4ng kh\u1EA3 d\u1EE5ng", "Penyimpanan modul peluncur tidak tersedia", "O armazenamento do m\u00F3dulo do lan\u00E7ador n\u00E3o est\u00E1 dispon\u00EDvel"),
